special_abilities:
  - { choose: 1, from: ["Background: Coastline/Rim", "Background: Desert/Back of Beyond", "Background: City"] }
  - name: "Background: Coastline/Rim"
    description: "Ability 1, for an athlete from the coast or the Rim, trained in harsh conditions: +1D4 and +2 to P.E. (the book prints P.E. twice), +1D4 to P.S., +1 to P.P., +1D6+1 to Spd, +1D6 to P.B. and +3D6+6 to physical S.D.C."
    bonuses: { attributes: { PE: "1d4+2", PS: "1d4", PP: 1, Spd: "1d6+1", PB: "1d6" }, pools: { sdc: "3d6+6" } }
  - name: "Background: Desert/Back of Beyond"
    description: "Ability 1, for an athlete from the desert or the Back of Beyond, raised in a bloody lifestyle: +1D6 to P.S., +1D4 to P.E., +2D6 to Spd, +2D6+12 to physical S.D.C., and a one-time +1D6 to starting Hit Points."
    bonuses: { attributes: { PS: "1d6", PE: "1d4", Spd: "2d6" }, pools: { sdc: "2d6+12", hp: "1d6" } }
  - name: "Background: City"
    description: "Ability 1, for a Tech-City athlete with professional facilities, muscle enhancing drugs and private coaches: +1D4+2 to P.S., +1D4 to P.P., +1 to P.E., +1D4 to P.B., +4 to Spd and +3D6+10 to physical S.D.C."
    bonuses: { attributes: { PS: "1d4+2", PP: "1d4", PE: 1, PB: "1d4", Spd: 4 }, pools: { sdc: "3d6+10" } }
  - name: "Specialty Bonuses Not on the Sheet"
    description: "Conditional or chosen parts of an area of expertise, added by hand. Archer Professional: +1 to strike and one extra bow attack per melee round. Ball Sports: +2 on initiative and +1 to strike when using a bat, club or other striking weapon. Bicyclist: +1 to dodge while on a bike; rides at three times normal running speed and holds top speed for P.E. x10 minutes. Professional Boxer and Gladiator: automatic dodge for the cost of two Secondary Skills. Professional Wrestler: all pin maneuvers. Surfer & Swimmer: +1D4 to M.A. or P.B. Target Shooter: +1 on aimed shots with the W.P.s of the specialty. White Water Sports: holds a speed in still water equal to P.S. x2 for P.E. x10 minutes."
  - name: "Multiple Specializations"
    description: "An athlete may specialize in more than one field. A second specialization halves the selection of O.C.C. Related Skills and halves the bonuses of the second specialization, rounding down, so +1 becomes no bonus; its skills and skill bonuses are unchanged. A third reduces the selection of O.C.C. Related Skills to two and halves the bonuses of the third the same way. The sheet holds one specialty; work a second or third out with the G.M."
